    def create_quote(self, symbol, price, quantity):
        quote_id = self.generate_quote_id()
        self.quotes[quote_id] = {
            'symbol': symbol,
            'price': price,
            'quantity': quantity,
            'status': self.quote_status['active'],
            'created_at': datetime.now(),
            'expires_at': datetime.now() + timedelta(seconds=self.timeout_seconds)
        }
