        return np.mean(returns)

    def calculate_volatility(self, returns):
        return np.std(returns)

    def calculate_sharpe_ratio(self, returns, risk_free_rate):
        excess_returns = returns - risk_free_rate
        return np.mean(excess_returns) / np.std(excess_returns)

    def calculate_max_drawdown(self, portfolio_values):
        cumulative_returns = (portfolio_values / portfolio_values[0]) * 100
        rolling_max = cumulative_returns.cummax()
        drawdowns = (rolling_max - cumulative_returns) / rolling_max
        return np.max(drawdowns)

    def calculate_sharpe_ratio(self, returns, risk_free_rate):
        excess_returns = returns - risk_free_rate
        return np.mean(excess_returns) / np.std(excess_returns)

    def calculate_sortino_ratio(self, returns, risk_free_rate):
        downside_returns = np.where(returns < risk_free_rate, returns - risk_free_rate, 0)
        downside_deviation = np.sqrt(np.mean(downside_returns**2))
        return np.mean(returns - risk_free_rate) / downside_deviation

    def calculate_calmar_ratio(self, returns, max_drawdown):
        annualized_return = np.mean(returns) * 252
        return annualized_return / max_drawdown

    def calculate_information_ratio(self, returns, benchmark_returns):
        excess_returns = returns - benchmark_returns
        return np.mean(excess_returns) / np.std(excess_returns)

    def calculate_alpha(self, returns, benchmark_returns, risk_free_rate):
        excess_returns = returns - benchmark_returns
        excess_benchmark_returns = benchmark_returns - risk_free_rate
        return np.mean(excess_returns) - np.mean(excess_benchmark_returns)

    def calculate_beta(self, returns, benchmark_returns):
        covariance = np.cov(returns, benchmark_returns)[0, 1]
        variance = np.var(benchmark_returns)
        return covariance / variance

    def calculate_treynor_ratio(self, returns, benchmark_returns):
        beta = self.calculate_beta(returns, benchmark_returns)
        return np.mean(returns) / beta

    def calculate_jensens_alpha(self, returns, benchmark_returns, risk_free_rate):
        beta = self.calculate_beta(returns, benchmark_returns)
        market_return = np.mean(benchmark_returns)
        alpha = np.mean(returns) - (risk_free_rate + beta * (market_return - risk_free_rate))
        return alpha

    def calculate_m2_ratio(self, returns, benchmark_returns):
        sigma = np.std(returns)
        sigma_benchmark = np.std(benchmark_returns)
        beta = self.calculate_beta(returns, benchmark_returns)
        m2 = (np.mean(returns) - np.mean(benchmark_returns)) / sigma_benchmark * sigma + np.mean(benchmark_returns)
        return m2

